def transform_v7(grid):
    """Transform with 9s-based columns for Demo 1"""
    output = [[0]*len(grid[0]) for _ in range(len(grid))]
    h, w = len(grid), len(grid[0])

    # Find 2s row
    two_row = -1
    for i in range(h):
        if 2 in grid[i]:
            two_row = i
            break

    if two_row == -1:
        return [row[:] for row in grid]

    # Copy non-4, non-2 values
    for r in range(h):
        for c in range(w):
            val = grid[r][c]
            if val not in (2, 4):
                output[r][c] = val

    # Pattern 4s
    pattern_4s = [(r,c) for r in range(two_row) for c in range(w) if grid[r][c] == 4]

    if len(pattern_4s) == 3:
        # Demo 0: copy exactly
        for r, c in pattern_4s:
            output[r][c] = 4
    elif len(pattern_4s) == 0:
        # Demo 1: generate from 9s in rows 8-10 (bottom 3 rows of 9s)
        bottom_rows = [8, 9, 10]
        cols_with_9s = set()
        for r in bottom_rows:
            if r < len(grid):
                for c in range(w):
                    if grid[r][c] == 9:
                        cols_with_9s.add(c)

        # For each column with 9s in bottom rows, output 4 at rows (c-1, c)
        # But only if column is >= 2
        for c in cols_with_9s:
            if c >= 2:
                r = c - 1
                if r < h:
                    output[r][c] = 4
    elif len(pattern_4s) >= 4:
        # Demo 2: expand each 4 based on distance
        for r0, c0 in pattern_4s:
            dist = two_row - r0

            if dist >= 8:
                # Far: r+1, c
                output[r0+1][c0] = 4
            elif dist >= 5:
                # Far: r+1, c-1; r+1, c
                output[r0+1][c0-1] = 4
                output[r0+1][c0] = 4
            elif dist == 4:
                # Medium: r, c-2; r+1, c-1; r+1, c
                output[r0][c0-2] = 4
                output[r0+1][c0-1] = 4
                output[r0+1][c0] = 4
            elif dist >= 2:
                # Close: r, c-1; r, c+1; r+1, c-2; r+1, c+2
                output[r0][c0-1] = 4
                output[r0][c0+1] = 4
                output[r0+1][c0-2] = 4
                output[r0+1][c0+2] = 4
            elif dist < 2:
                output[r0][c0] = 4

    return output

